structs.rhbloom:
struct rhbloom
{
    void *(*malloc)(size_t);
    void (*free)(void *);
    size_t count;
    size_t nbuckets;
    uint64_t *buckets;
    size_t k;
    size_t m;
    uint8_t *bits;
}

functions.rhbloom_new_with_allocator:
struct rhbloom *rhbloom_new_with_allocator(size_t n, double p, void *(*_malloc)(size_t), void (*_free)(void *))
{
    if (n < 16)
        n = 16;
    size_t m = n * log(p) / log(1 / pow(2, log(2)));
    size_t k = round(((double)m / (double)(n)) * log(2));
    size_t m0 = 2;
    while (m0 < m)
    {
        m0 *= 2;
    }
    size_t k0 = round((double)m / (double)m0 * (double)k);
    _malloc = _malloc ? _malloc : malloc;
    _free = _free ? _free : free;
    struct rhbloom *rhbloom = _malloc(sizeof(struct rhbloom));
    if (!_malloc)
    {
        return 0;
    }
    rhbloom->malloc = _malloc;
    rhbloom->free = _free;
    rhbloom->count = 0;
    rhbloom->nbuckets = 0;
    rhbloom->buckets = 0;
    rhbloom->k = k0;
    rhbloom->m = m0;
    rhbloom->bits = 0;
    return rhbloom;
}

functions.rhbloom_new:
struct rhbloom *rhbloom_new(size_t n, double p)
{
    return rhbloom_new_with_allocator(n, p, malloc, free);
}

functions.rhbloom_free:
void rhbloom_free(struct rhbloom *rhbloom)
{
    if (rhbloom->bits)
    {
        rhbloom->free(rhbloom->bits);
    }
    if (rhbloom->buckets)
    {
        rhbloom->free(rhbloom->buckets);
    }
    rhbloom->count = 0;
    rhbloom->nbuckets = 0;
    rhbloom->buckets = 0;
    rhbloom->bits = 0;
    rhbloom->free(rhbloom);
}

functions.rhbloom_mix:
static uint64_t rhbloom_mix(uint64_t key)
{
    key ^= key >> 30;
    key *= 0xbf58476d1ce4e5b9UL;
    key ^= key >> 27;
    key *= 0x94d049bb133111ebUL;
    key ^= key >> 31;
    return key;
}

functions.rhbloom_testadd:
static _Bool rhbloom_testadd(struct rhbloom *rhbloom, uint64_t key, _Bool add)
{
    key = ((uint64_t)(key) << 8 >> 8);
    size_t i = 0;
    size_t j = key & (rhbloom->m - 1);
    while (1)
    {
        if (add)
        {
            rhbloom->bits[j >> 3] |= add << (j & 7);
        }
        else if (!((rhbloom->bits[j >> 3] >> (j & 7)) & 1))
        {
            return 0;
        }
        if (i == rhbloom->k - 1)
        {
            break;
        }
        key *= 0x94d049bb133111ebUL;
        key ^= key >> 31;
        j = key & (rhbloom->m - 1);
        i++;
    }
    return 1;
}

functions.rhbloom_grow:
static _Bool rhbloom_grow(struct rhbloom *rhbloom)
{
    size_t nbuckets_old = rhbloom->nbuckets;
    uint64_t *buckets_old = rhbloom->buckets;
    size_t nbuckets_new = nbuckets_old == 0 ? 16 : nbuckets_old * 2;
    if (nbuckets_new * 8 >= rhbloom->m >> 3)
    {
        rhbloom->bits = rhbloom->malloc(rhbloom->m >> 3);
        if (!rhbloom->bits)
        {
            return 0;
        }
        memset(rhbloom->bits, 0, rhbloom->m >> 3);
        rhbloom->count = 0;
        rhbloom->nbuckets = 0;
        rhbloom->buckets = 0;
        for (size_t i = 0; i < nbuckets_old; i++)
        {
            if ((int)((uint64_t)(buckets_old[i]) >> 56))
            {
                rhbloom_testadd(rhbloom, buckets_old[i], 1);
            }
        }
    }
    else
    {
        uint64_t *buckets = rhbloom->malloc(nbuckets_new << 3);
        if (!buckets)
        {
            return 0;
        }
        memset(buckets, 0, nbuckets_new << 3);
        rhbloom->count = 0;
        rhbloom->nbuckets = nbuckets_new;
        rhbloom->buckets = buckets;
        for (size_t i = 0; i < nbuckets_old; i++)
        {
            if ((int)((uint64_t)(buckets_old[i]) >> 56))
            {
                rhbloom_addkey(rhbloom, buckets_old[i]);
            }
        }
    }
    if (buckets_old)
    {
        rhbloom->free(buckets_old);
    }
    return 1;
}

functions.rhbloom_addkey:
static _Bool rhbloom_addkey(struct rhbloom *rhbloom, uint64_t key)
{
    key = ((uint64_t)(key) << 8 >> 8);
    int dib = 1;
    size_t i = key & (rhbloom->nbuckets - 1);
    while (1)
    {
        if ((int)((uint64_t)(rhbloom->buckets[i]) >> 56) == 0)
        {
            rhbloom->buckets[i] = (((uint64_t)((key)) << 8 >> 8) | ((uint64_t)(dib) << 56));
            rhbloom->count++;
            return 1;
        }
        if (((uint64_t)(rhbloom->buckets[i]) << 8 >> 8) == key)
        {
            return 1;
        }
        if ((int)((uint64_t)(rhbloom->buckets[i]) >> 56) < dib)
        {
            uint64_t tmp = rhbloom->buckets[i];
            rhbloom->buckets[i] = (((uint64_t)((key)) << 8 >> 8) | ((uint64_t)(dib) << 56));
            key = ((uint64_t)(tmp) << 8 >> 8);
            dib = (int)((uint64_t)(tmp) >> 56);
        }
        dib++;
        i = (i + 1) & (rhbloom->nbuckets - 1);
    }
}

functions.rhbloom_add:
_Bool rhbloom_add(struct rhbloom *rhbloom, uint64_t key)
{
    key = rhbloom_mix(key);
    while (1)
    {
        if (rhbloom->bits)
        {
            rhbloom_testadd(rhbloom, key, 1);
            return 1;
        }
        if (rhbloom->count == rhbloom->nbuckets >> 1)
        {
            if (!rhbloom_grow(rhbloom))
            {
                return 0;
            }
            continue;
        }
        break;
    }
    return rhbloom_addkey(rhbloom, key);
}

functions.rhbloom_test:
_Bool rhbloom_test(struct rhbloom *rhbloom, uint64_t key)
{
    key = rhbloom_mix(key);
    if (rhbloom->bits)
    {
        return rhbloom_testadd(rhbloom, key, 0);
    }
    if (!rhbloom->buckets)
    {
        return 0;
    }
    key = ((uint64_t)(key) << 8 >> 8);
    int dib = 1;
    size_t i = key & (rhbloom->nbuckets - 1);
    while (1)
    {
        _Bool yes = ((uint64_t)(rhbloom->buckets[i]) << 8 >> 8) == key;
        _Bool no = (int)((uint64_t)(rhbloom->buckets[i]) >> 56) < dib;
        if (yes || no)
        {
            return yes;
        }
        dib++;
        i = (i + 1) & (rhbloom->nbuckets - 1);
    }
}

functions.rhbloom_memsize:
size_t rhbloom_memsize(struct rhbloom *rhbloom)
{
    size_t size = sizeof(struct rhbloom);
    size += rhbloom->bits ? rhbloom->m >> 3 : rhbloom->nbuckets << 3;
    return size;
}

functions.rhbloom_clear:
void rhbloom_clear(struct rhbloom *rhbloom)
{
    if (rhbloom->bits)
    {
        memset(rhbloom->bits, 0, rhbloom->m >> 3);
    }
    else if (rhbloom->buckets)
    {
        memset(rhbloom->buckets, 0, rhbloom->nbuckets << 3);
        rhbloom->count = 0;
    }
}
